from machine import UART, Pin
import time
from neo7m import NEO7M

uart = UART({UART_ID}, baudrate=9600, tx=Pin({RXD}), rx=Pin({TXD}))
gps = NEO7M(uart)
while True:
    if gps.update():
        if gps.fix and gps.latitude is not None:
            print('LAT=%.4f LON=%.4f ALT=%.1fm SPD=%.1fkn' % (gps.latitude, gps.longitude, gps.altitude or 0, gps.speed_knots or 0))
        else:
            print('Waiting for fix...')
    time.sleep_ms(200)
